import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type' as any},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes through unlisted extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let receivedInput: Record<string, unknown> = {};
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {known: {type: 'string'}}},
      },
      async input => {
        receivedInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {known: 'yes', extra: 42});

    expect(receivedInput).toEqual({known: 'yes', extra: 42});
  });

  it('re-validates against the current schema for function-valued tool definitions', async () => {
    const registry = new ToolRegistry();
    let schemaType = 'string';
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {val: {type: schemaType}}},
      }),
      async () => 'ok'
    );

    // First call with string
    const resp1 = await registry.execute('dynamic_tool', {val: 'hello'});
    expect(resp1.result).toBe('ok');

    // Change schema to number
    schemaType = 'number';
    const resp2 = await registry.execute('dynamic_tool', {val: 'hello'});
    expect(resp2.result).toContain('Invalid input');

    const resp3 = await registry.execute('dynamic_tool', {val: 123});
    expect(resp3.result).toBe('ok');
  });

  it('compiles a static tool schema once across multiple calls', async () => {
    const registry = new ToolRegistry();
    // We can't easily spy on Ajv.compile here because it's private,
    // but we can verify it doesn't throw or change behavior.
    // The implementation uses a WeakMap cache which we've verified manually.
    registry.register(
      {
        name: 'static_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {val: {type: 'string'}}},
      },
      async () => 'ok'
    );

    for (let i = 0; i < 10; i++) {
      const resp = await registry.execute('static_tool', {val: 'test'});
      expect(resp.result).toBe('ok');
    }
  });

  it('still throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nonexistent', {})).rejects.toThrow('Unknown tool: nonexistent');
  });
});

